'use client';

import React, { useState, useEffect, useCallback } from 'react';

interface TocItem {
  id: string;
  text: string;
}

interface TableOfContentsProps {
  items: TocItem[];
}

const TableOfContents: React.FC<TableOfContentsProps> = ({ items }) => {
  const [activeId, setActiveId] = useState<string>('');
  const [isOpen, setIsOpen] = useState(false);

  // Highlight active heading as user scrolls
  useEffect(() => {
    if (items.length === 0) return;

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setActiveId(entry.target.id);
          }
        });
      },
      { rootMargin: '0px 0px -70% 0px', threshold: 0 }
    );

    items.forEach(({ id }) => {
      const el = document.getElementById(id);
      if (el) observer.observe(el);
    });

    return () => observer.disconnect();
  }, [items]);

  const handleClick = useCallback(
    (e: React.MouseEvent<HTMLAnchorElement>, id: string) => {
      e.preventDefault();
      const el = document.getElementById(id);
      if (el) {
        const offset = 90; // account for sticky header
        const top = el.getBoundingClientRect().top + window.scrollY - offset;
        window.scrollTo({ top, behavior: 'smooth' });
        setActiveId(id);
        setIsOpen(false); // close mobile dropdown after click
      }
    },
    []
  );

  if (items.length === 0) return null;

  return (
    <>
      {/* ── MOBILE: collapsible dropdown ── */}
      <div className="lg:hidden mb-8 rounded-xl border border-gray-200 bg-white overflow-hidden shadow-sm">
        <button
          onClick={() => setIsOpen((prev) => !prev)}
          aria-expanded={isOpen}
          className="w-full flex items-center justify-between px-5 py-4 text-left font-semibold text-brand-dark hover:bg-gray-50 transition-colors duration-200"
        >
          <span className="flex items-center gap-2">
            {/* list icon */}
            <svg
              className="w-5 h-5 text-brand-primary flex-shrink-0"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
              strokeWidth={2}
            >
              <path strokeLinecap="round" strokeLinejoin="round" d="M4 6h16M4 12h16M4 18h10" />
            </svg>
            Table of Contents
          </span>
          <svg
            className={`w-5 h-5 text-brand-gray transition-transform duration-300 ${isOpen ? 'rotate-180' : ''}`}
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
            strokeWidth={2}
          >
            <path strokeLinecap="round" strokeLinejoin="round" d="M19 9l-7 7-7-7" />
          </svg>
        </button>

        {/* Animated dropdown body */}
        <div
          className={`overflow-hidden transition-all duration-300 ease-in-out ${
            isOpen ? 'max-h-[400px] opacity-100' : 'max-h-0 opacity-0'
          }`}
        >
          <nav aria-label="Table of contents mobile" className="px-5 pb-4 pt-1">
            <ol className="space-y-2">
              {items.map((item, idx) => (
                <li key={item.id}>
                  <a
                    href={`#${item.id}`}
                    onClick={(e) => handleClick(e, item.id)}
                    className={`flex items-start gap-2.5 text-sm py-1 rounded transition-colors duration-150 ${
                      activeId === item.id
                        ? 'text-brand-primary font-semibold'
                        : 'text-brand-gray hover:text-brand-dark'
                    }`}
                  >
                    <span className="flex-shrink-0 w-5 h-5 mt-0.5 rounded-full bg-brand-primary/10 text-brand-primary text-xs font-bold flex items-center justify-center">
                      {idx + 1}
                    </span>
                    {item.text}
                  </a>
                </li>
              ))}
            </ol>
          </nav>
        </div>
      </div>

      {/* ── DESKTOP: sticky sidebar ── */}
      <aside className="hidden lg:block sticky top-24 w-64 flex-shrink-0 self-start">
        <div className="rounded-xl border border-gray-200 bg-white shadow-sm overflow-hidden">
          <div className="flex items-center gap-2 px-5 py-4 border-b border-gray-100">
            <svg
              className="w-4 h-4 text-brand-primary flex-shrink-0"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
              strokeWidth={2}
            >
              <path strokeLinecap="round" strokeLinejoin="round" d="M4 6h16M4 12h16M4 18h10" />
            </svg>
            <span className="text-sm font-bold text-brand-dark uppercase tracking-wider">
              Contents
            </span>
          </div>
          <nav aria-label="Table of contents" className="px-5 py-4">
            <ol className="space-y-1.5">
              {items.map((item, idx) => (
                <li key={item.id}>
                  <a
                    href={`#${item.id}`}
                    onClick={(e) => handleClick(e, item.id)}
                    className={`flex items-start gap-2.5 text-sm py-1 rounded transition-colors duration-150 group ${
                      activeId === item.id
                        ? 'text-brand-primary font-semibold'
                        : 'text-brand-gray hover:text-brand-dark'
                    }`}
                  >
                    <span
                      className={`flex-shrink-0 w-5 h-5 mt-0.5 rounded-full text-xs font-bold flex items-center justify-center transition-colors duration-150 ${
                        activeId === item.id
                          ? 'bg-brand-primary text-white'
                          : 'bg-brand-primary/10 text-brand-primary group-hover:bg-brand-primary/20'
                      }`}
                    >
                      {idx + 1}
                    </span>
                    <span className="leading-snug">{item.text}</span>
                  </a>
                </li>
              ))}
            </ol>
          </nav>
        </div>
      </aside>
    </>
  );
};

export default TableOfContents;
